E.verifyReferences=function(){
 const reports=[];
 for(const r of REFERENCES){const e=E.createEngine(E.PRESETS[r.id]);let maximum=0,checked=0;
  for(let k=0;k<r.indices.length;k++){while(e.index<r.indices[k])e.step();const row=e.sample();for(let j=0;j<r.columns.length;j++){const error=Math.abs(row[j]-r.data[k][j]);if(!Number.isFinite(error)||error>1e-6)throw Error('MATLAB reference mismatch: '+r.id+' '+r.columns[j]+' step '+e.index+' error '+error);maximum=Math.max(maximum,error);checked++;}}
  reports.push({case:r.id,checkpoints:r.indices.length,values:checked,maximumAbsoluteDifference:maximum});
 }return reports;
};
E.selfTest=function(){
 const checks=[];const test=(name,ok)=>{if(!ok)throw Error(name);checks.push(name);};
 const rejects=(x)=>{try{E.validate(x);return false;}catch{return true;}};
 for(const x of [{Cdc:0},{ramp_s:0},{speed_rpm:-1},{speed_rpm:2600},{load_after:36},{Vb:99},{buckD:.9},{pp:2.5},{switching:2},{Rs:NaN},{fci:1e8},{duration:100},{record_s:1e-7},{unknown:1}])test('Reject '+Object.keys(x)[0]+'='+Object.values(x)[0],rejects(x));
 const r=E.simulate(),I=E.INDEX,last=r.rows.at(-1),get=k=>last[I[k]];
 test('Default speed tracks 1500 rpm',Math.abs(get('drive_speed_rpm_2')-1500)<1e-6);
 test('Torque includes viscous friction',Math.abs(get('drive_torque_Nm_1')-(20+.001*1500*Math.PI/30))<1e-7);
 test('Buck settles to 300 V',Math.abs(get('buck_voltages_2')-300)<1e-6);
 test('Boost settles to 400 V',Math.abs(get('boost_voltages_2')-400)<1e-6);
 test('Recorded CSV has 5001 rows',r.rows.length===5001&&E.toCSV(r).trim().split('\n').length===5002);
 test('Fine window uses solver step',Math.abs(r.fine[1][0]-r.fine[0][0]-r.dt)<1e-12);
 let balanced=true,power=true,gates=true,duties=true,finite=true;
 for(const row of r.rows){finite&&=row.every(Number.isFinite);balanced&&=Math.abs(row[11]+row[12]+row[13])<1e-8;power&&=Math.abs(row[8]-row[5]*row[22])<1e-6;gates&&=row.slice(23,26).every((v,j)=>(v===0||v===1)&&v+row[26+j]===1);duties&&=row.slice(29,32).every(v=>v>=0&&v<=1);}
 test('All values finite',finite);test('Three-phase currents sum to zero',balanced);test('Ideal inverter power conservation',power);test('Six complementary binary gates',gates);test('Duties stay within 0 to 1',duties);
 const s=E.simulate(E.PRESETS.steady),a=s.rows[0],b=s.rows.at(-1);
 test('Lossy buck starts at correct equilibrium',Math.abs(a[I.buck_voltages_2]-300*80/82)<1e-9&&Math.abs(b[I.buck_voltages_2]-a[I.buck_voltages_2])<1e-8);
 test('Lossy boost starts at correct equilibrium',Math.abs(a[I.boost_voltages_2]-300*.75*80/(.75**2*80+2))<1e-9&&Math.abs(b[I.boost_voltages_2]-a[I.boost_voltages_2])<1e-8);
 const zero=E.simulate({speed_rpm:0,load_before:0,load_after:0,duration:.02});test('Zero command stays at rest',zero.rows.every(row=>Math.abs(row[I.drive_speed_rpm_2])<1e-10));
 const limited=E.simulate({speed_rpm:2500,load_before:35,load_after:35,Imax:10,duration:.02});test('Unavailable torque does not reverse shaft',limited.rows.every(row=>row[I.drive_speed_rpm_2]>=0));
 const coarse=E.simulate({record_s:.01});test('Recording interval does not alter numerics',coarse.rows.at(-1).every((v,j)=>v===last[j]));
 const load=E.createEngine({duration:.02,step_s:.01});while(load.index<499)load.step();test('Load before step',load.sample()[4]===10);load.step();test('Load changes at step',load.sample()[4]===20);
 return {status:'PASS',checks:checks.length,results:checks,references:E.verifyReferences()};
};
E.brief='Integrate this tested engine into the virtual platform. Deliver an operational responsive interface with connected source–DC link–PWM inverter–PMSM visual, a shaft-driven rotor or wheel, synchronized speed/torque/DC/power plots, true solver-resolution phase/PWM plots, separate buck/boost/rectifier experiments, editable validated parameters, presets, pause/reset/seek, CSV export and keyboard access. Car illustration is optional and kinematic only. No SOC, distance, regen or thermal claims. Run self-tests and browser checks; provide desktop/mobile screenshots and actual test evidence. Static mockups alone do not satisfy completion.';
E.verifyNativeDirectory=function(directory){
 if(typeof require!=='function')throw Error('Native binary verification requires Node.');
 const fs=require('node:fs'),path=require('node:path'),reports=[];
 for(const id of ['default','changed','pwm']){
  const meta=JSON.parse(fs.readFileSync(path.join(directory,id+'_native.json'),'utf8')),buffer=fs.readFileSync(path.join(directory,id+'_native.bin'));
  const e=E.createEngine(E.PRESETS[id]),n=47,expected=Math.round(e.config.duration/e.dt)+1;
  if(meta.rows!==expected||JSON.stringify(meta.columns)!==JSON.stringify(E.COLUMNS.slice(0,n))||buffer.length!==expected*n*8)throw Error('Native reference schema or length mismatch: '+id);
  let maximum=0;
  for(let i=0;i<expected;i++){const row=e.sample();for(let j=0;j<n;j++){const delta=Math.abs(row[j]-buffer.readDoubleLE((i*n+j)*8));if(!Number.isFinite(delta)||delta>1e-6)throw Error('Native mismatch '+id+' step '+i+' '+meta.columns[j]+' error '+delta);maximum=Math.max(maximum,delta);}if(i<expected-1)e.step();}
  reports.push({case:id,rows:expected,channels:n,maximumAbsoluteDifference:maximum});
 }return reports;
};
if(typeof module==='object'&&module.exports&&require.main===module){
 const fs=require('node:fs');const [command,destination]=process.argv.slice(2);
 try{
  if(command==='--self-test')console.log(JSON.stringify(E.selfTest(),null,2));
  else if(command==='--verify-native'){if(!destination)throw Error('Provide the directory of genuine MATLAB exports.');console.log(JSON.stringify(E.verifyNativeDirectory(destination),null,2));}
  else if(command==='--brief')console.log(E.brief);
  else if(command==='--demo'){
   if(!destination)throw Error('Provide a new HTML output filename.');
   const source=fs.readFileSync(__filename,'utf8').replace(/<\/script/gi,'<\\/script');
   const html='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edward BEV Virtual Engineering Lab</title><style>body{margin:0;padding:20px;background:#e5edf2}@media(max-width:600px){body{padding:0}}</style><div id="edward-lab"></div><script>'+source+'</script><script>globalThis.edwardLab=EdwardBEV.mount(document.getElementById("edward-lab"));</script></html>';
   fs.writeFileSync(destination,html,{flag:'wx'});console.log('Created '+destination);
  }else throw Error('Usage: node Edward_BEV_Virtual_Platform.cjs --self-test | --brief | --demo NEW.html | --verify-native DIRECTORY');
 }catch(e){console.error(e.message);process.exitCode=1;}
}
